import{_ as o,r as s,o as p,c as i,e as t,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Defining Options - October CMS - 3.x","titleTemplate":false,"description":"Defining the options property used across many definitions.","frontmatter":{"subtitle":"Defining the options property used across many definitions."},"headers":[{"level":2,"title":"Option Arrays","slug":"option-arrays","link":"#option-arrays","children":[]},{"level":2,"title":"Option Presets","slug":"option-presets","link":"#option-presets","children":[]},{"level":2,"title":"Option Methods","slug":"option-methods","link":"#option-methods","children":[{"level":3,"title":"Detailed Option Definitions","slug":"detailed-option-definitions","link":"#detailed-option-definitions","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"3.x/element/define-options.md","filePath":"3.x/element/define-options.md"}'),r={name:"3.x/element/define-options.md"};function d(u,n,g,k,h,f){const a=s("pre-heading"),e=s("post-heading");return p(),i("div",null,[t(a),n[0]||(n[0]=l("h1",null,"Defining Options",-1)),t(e),n[1]||(n[1]=c(`<p>Commonly, you may encounter the <strong>options</strong>, <strong>optionsMethod</strong> or <strong>optionsPreset</strong> property, this article describes in more detail how to configure options.</p><h2 id="option-arrays"><a href="#option-arrays" class="header-anchor">#</a> Option Arrays</h2><p>The <code>options</code> property should specify the options directly as part of the definition as a key-value pair, where the value and label are independently specified.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">draft</span><span class="token punctuation">:</span> Draft
    <span class="token key atrule">published</span><span class="token punctuation">:</span> Published
    <span class="token key atrule">archived</span><span class="token punctuation">:</span> Archived
</code></pre></div><p>The keys can be integers with their label.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">1</span><span class="token punctuation">:</span> Simple
    <span class="token key atrule">2</span><span class="token punctuation">:</span> Complex
</code></pre></div><p>In addition to a simple arrays, some fields such as <a href="./form/field-radio.html">radio lists</a> support specifying a description as part of their <code>options</code> values. This is where the value is defined as another array with the syntax <code>key: [label, description]</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">all</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>All<span class="token punctuation">,</span> Guests and customers will be able to access this page.<span class="token punctuation">]</span>
    <span class="token key atrule">registered</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Registered only<span class="token punctuation">,</span> Only logged in member will be able to access this page.<span class="token punctuation">]</span>
    <span class="token key atrule">guests</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Guests only<span class="token punctuation">,</span> Only guest users will be able to access this page.<span class="token punctuation">]</span>
</code></pre></div><p>Other fields, such as <a href="./form/field-dropdown.html">dropdown fields</a> support specifying an icon, image or color as part of their <code>options</code> values. If the second item in the array starts with a <code>#</code> then it is considered a color, and if the value contains a <code>.</code> then it is considered an image, otherwise it is considered an icon class.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">red</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Color<span class="token punctuation">,</span> <span class="token string">&#39;#ff0000&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Icon<span class="token punctuation">,</span> <span class="token string">&#39;oc-icon-calendar&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">image</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Image<span class="token punctuation">,</span> <span class="token string">&#39;/path/to/image.png&#39;</span><span class="token punctuation">]</span>
</code></pre></div><h2 id="option-presets"><a href="#option-presets" class="header-anchor">#</a> Option Presets</h2><p>The <code>optionsPreset</code> property specifies a preset code that can be used to request the available options.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsPreset</span><span class="token punctuation">:</span> icons
</code></pre></div><p>The following presets are available:</p><div class="table"><table tabindex="0"><thead><tr><th>Preset</th><th>Description</th></tr></thead><tbody><tr><td><strong>icons</strong></td><td>Lists available icon names (eg: <code>icon-calendar</code>)</td></tr><tr><td><strong>phosphorIcons</strong></td><td>Lists available icon names (eg: <code>ph ph-calendar</code>)</td></tr><tr><td><strong>locales</strong></td><td>Lists available locales (eg: <code>en-au</code>)</td></tr><tr><td><strong>flags</strong></td><td>Lists locales with their icons as flags (eg: <code>[en-au, flag-au]</code>)</td></tr><tr><td><strong>timezones</strong></td><td>Lists available timezones (eg: <code>Australia/Sydney</code>)</td></tr></tbody></table></div><h2 id="option-methods"><a href="#option-methods" class="header-anchor">#</a> Option Methods</h2><p>The <code>optionsMethod</code> property specifies a callable PHP method that can be used to request the available options. Typically the method name will refer to a method local to the associated model.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> getMyOptionsFromModel
</code></pre></div><p>The method name can also be a static method on any object.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> MyAuthor\\MyPlugin\\Helpers\\FormHelper<span class="token punctuation">:</span><span class="token punctuation">:</span>getMyStaticMethodOptions
</code></pre></div><h3 id="detailed-option-definitions"><a href="#detailed-option-definitions" class="header-anchor">#</a> Detailed Option Definitions</h3><p>Inside the method, an detailed definition can be used to specify more advanced options, such as setting individual attributes for each option. A detailed definition is identified by its associated array structure.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getDetailedFieldOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token number">1</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 1&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option one&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token number">2</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 2&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option two&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;disabled&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The following properties are supported where possible:</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the option to the user.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the option label.</td></tr><tr><td><strong>readOnly</strong></td><td>specifies if the option is read-only or not.</td></tr><tr><td><strong>disabled</strong></td><td>specifies if the option is disabled or not.</td></tr><tr><td><strong>hidden</strong></td><td>defines the option without ever displaying it.</td></tr><tr><td><strong>color</strong></td><td>defines a status indicator color for the option as a hex color (dropdown)</td></tr><tr><td><strong>icon</strong></td><td>specifies an icon name for this option (dropdown)</td></tr><tr><td><strong>image</strong></td><td>specifies an image URL for this option (dropdown)</td></tr><tr><td><strong>optgroup</strong></td><td>set to <code>true</code> if the children should belong to an option group structure, default: <code>false</code> (dropdown)</td></tr><tr><td><strong>children</strong></td><td>specifies child options as another array for a nested structure (checkbox list)</td></tr></tbody></table></div><p>Use the <code>children</code> property if the option definition supports nesting. Generally, this will display a structure for checkbox lists and implement an option group for dropdowns.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getDetailedFieldOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token number">1</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 1&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option one&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;children&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token number">2</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 2&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option two&#39;</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token comment">// ...</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./form/field-checkboxlist.html">Checkbox List Field</a></li><li><a href="./form/field-dropdown.html">Dropdown Field</a></li><li><a href="./form/field-radio.html">Radio Field</a></li></ul></div>`,29))])}const b=o(r,[["render",d]]);export{y as __pageData,b as default};
